draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // limit line
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 100 + 50*Math.sin(t));
  ctx.lineTo(W, H/2 + 100 + 50*Math.sin(t));
  ctx.stroke();

  // character movement
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50 + 20*Math.sin(t), 5, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
